import{_ as e,o as t,c as o,a2 as r}from"./chunks/framework.Crpw6aS5.js";const c=JSON.parse('{"title":"1965年 核心总结","description":"","frontmatter":{},"headers":[],"relativePath":"01_letters/1965年/核心总结.md","filePath":"01_letters/1965年/核心总结.md"}'),n={name:"01_letters/1965年/核心总结.md"};function l(s,a,i,_,h,d){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="_1965年-核心总结" tabindex="-1">1965年 核心总结 <a class="header-anchor" href="#_1965年-核心总结" aria-label="Permalink to &quot;1965年 核心总结&quot;">​</a></h1><h2 id="年度业绩" tabindex="-1">年度业绩 <a class="header-anchor" href="#年度业绩" aria-label="Permalink to &quot;年度业绩&quot;">​</a></h2><p>1965年，道琼斯指数上涨14.2%，而巴菲特合伙企业实现了惊人的47.2%收益率，创下当时史上最大超额收益纪录——跑赢指数33个百分点。合伙企业净资产从1740万美元大幅增长，管理规模与业绩均创下新高。这一年标志着巴菲特投资生涯的一个重要转折点，其方法论的有效性得到了充分验证。</p><h2 id="重要事件" tabindex="-1">重要事件 <a class="header-anchor" href="#重要事件" aria-label="Permalink to &quot;重要事件&quot;">​</a></h2><p>伯克希尔·哈撒韦在这一年成为巴菲特合伙企业的控股持仓，这是巴菲特首次实质性控制一家上市公司。巴菲特随后指派肯·蔡斯（Ken Chase）接管伯克希尔纺织业务的管理，着手改善这家陷入困境的纺织企业的运营。这一举措标志着巴菲特从纯粹的二级市场股票投资，开始向企业并购与实业经营领域延伸。</p><p>同年，巴菲特在投资策略上新增了&quot;40%集中规则&quot;——即在满足特定安全边际条件下，单一标的的投资上限可提升至合伙企业净资产的40%。这一规则的引入，使他得以在极度确信的机会面前大胆重仓，为后续的集中投资策略提供了制度化依据。</p><h2 id="投资理念" tabindex="-1">投资理念 <a class="header-anchor" href="#投资理念" aria-label="Permalink to &quot;投资理念&quot;">​</a></h2><p>巴菲特逐步形成了一个核心认知：真正的投资超额回报，来自对企业内在价值与市场价格之间差距的深度研究，而非依赖市场整体趋势或短期情绪。他开始更加重视&quot;定性&quot;因素——管理层的诚信与能力、企业的竞争护城河——而不只是&quot;定量&quot;层面的账面价值与市盈率。这一理念的演化，为他日后从&quot;捡烟蒂&quot;转向&quot;以合理价格买进优质企业&quot;埋下了伏笔。</p><h2 id="关键人物" tabindex="-1">关键人物 <a class="header-anchor" href="#关键人物" aria-label="Permalink to &quot;关键人物&quot;">​</a></h2><p>肯·蔡斯（Ken Chase）在这一年受巴菲特委派，全面接管伯克希尔·哈撒韦纺织业务的日常运营。蔡斯的务实管理风格与巴菲特形成了良好的互补，为日后伯克希尔的转型奠定了运营基础。与此同时，斯坦·鲁梅尔特（Stan Rummel）作为财务与合规的关键人物，持续为合伙企业提供支持。</p>',10)])])}const p=e(n,[["render",l]]);export{c as __pageData,p as default};
